#!/usr/bin/env bash
set -euo pipefail

CODEFORGE_TOKEN="${CODEFORGE_TOKEN:-$(openssl rand -hex 24 2>/dev/null || python3 -c "import secrets; print(secrets.token_hex(24))" 2>/dev/null || cat /dev/urandom | tr -dc 'a-zA-Z0-9' | fold -w 48 | head -n 1)}"
CODEFORGE_ROOT="/opt/codeforge-mobile"
PROJECT_PATH="/root/codeforge-project"
SERVER_FILE="$CODEFORGE_ROOT/codeforge-remote-server.mjs"
SERVICE_FILE="/etc/systemd/system/codeforge-remote.service"

apt update
apt install -y curl git nodejs npm

if ! command -v codex >/dev/null 2>&1; then
  curl -fsSL https://chatgpt.com/codex/install.sh | sh
fi
if command -v codex >/dev/null 2>&1; then
  ln -sf "$(command -v codex)" /usr/local/bin/codex
elif [ -x /root/.local/bin/codex ]; then
  ln -sf /root/.local/bin/codex /usr/local/bin/codex
fi

if ! command -v agy >/dev/null 2>&1; then
  curl -fsSL https://antigravity.google/cli/install.sh | bash || true
fi
if command -v agy >/dev/null 2>&1; then
  ln -sf "$(command -v agy)" /usr/local/bin/agy
elif [ -x /root/.local/bin/agy ]; then
  ln -sf /root/.local/bin/agy /usr/local/bin/agy
fi

mkdir -p "$CODEFORGE_ROOT" "$PROJECT_PATH"REMOTE_SERVER_B64=""

printf '%s' "$REMOTE_SERVER_B64" | base64 -d > "$SERVER_FILE"
chmod 755 "$SERVER_FILE"

cat > "$SERVICE_FILE" <<EOF_SERVICE
[Unit]
Description=CodeForge Mobile Remote API
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
Environment=CODEFORGE_TOKEN=$CODEFORGE_TOKEN
Environment=CODEFORGE_HOST=0.0.0.0
Environment=CODEFORGE_PORT=8787
Environment=PATH=/root/.local/bin:/usr/local/bin:/usr/bin:/bin
WorkingDirectory=$PROJECT_PATH
ExecStart=/usr/bin/node $SERVER_FILE
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF_SERVICE

systemctl daemon-reload
systemctl enable --now codeforge-remote.service
if command -v ufw >/dev/null 2>&1; then
  ufw allow 8787/tcp || true
fi
systemctl status codeforge-remote.service --no-pager

echo
echo "Lokaler API-Test:"
curl -fsS -H "Authorization: Bearer $CODEFORGE_TOKEN" http://127.0.0.1:8787/health || true

echo
echo "Port-Status:"
ss -ltnp | grep ':8787' || true

echo
echo "CodeForge Remote API: http://88.214.56.241:8787"
echo "Token: $CODEFORGE_TOKEN"
echo "Projektpfad: $PROJECT_PATH"
echo
echo "Wichtig: Fuehre danach einmal 'codex login' aus, falls Codex noch nicht angemeldet ist."
